import{z as o,x as s,o as t,c as B,q as e,j as A,D as i,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"AQLM","description":"","frontmatter":{"title":"AQLM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aqlm.md","filePath":"llm/aqlm.md","lastUpdated":1791063341000}'),p={name:"llm/aqlm.md"};function d(m,a,u,M,h,b){const E=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=e('<h1 id="aqlm" tabindex="-1">AQLM <a class="header-anchor" href="#aqlm" aria-label="Permalink to &quot;AQLM&quot;">​</a></h1><div class="epigraph"><p>把一行权重写成若干码本向量之和，比特预算花在「选哪几个码字」而不是「每个标量均分 2 bit」；再在校准上微调码本，2-bit 的帕累托才能从均匀格子里逃出来。</p><footer>—— Egiazarian 等，Extreme Compression of Large Language Models via Additive Quantization，ICML 2024</footer></div><p>Vage Egiazarian、Andrei Panferov、Denis Kuznedelev、Elias Frantar、Artem Babenko 与 Dan Alistarh 的 ICML 2024 论文（arXiv:2401.06118）把计算机视觉里的 <strong>加法量化</strong>（Additive Quantization, AQ）接到 LLM 权重上，简称 AQLM。一层权重的一组坐标不再共享一个均匀尺度，而是表示为 \\(M\\) 个码本各自查表再相加。2-bit 附近它与 <a href="/llm/quip">QuIP#</a> 反复争夺帕累托前沿：谁赢取决于码本微调、分组维度与是否同一校准。Alistarh 组同时出现在 GPTQ、QuaRot 等谱系里，但 AQLM 的推理原语是 <strong>多码本查表</strong>，不是 INT4 GEMM，也不是 E8 格的最近邻。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀 2-bit 每元素四个电平，无法表达权重里残留的相干结构。GPTQ 改的是取整顺序与邻居补偿，格子本身仍是均匀的。向量量化（VQ）给一组坐标共用一本码，表达力强，但码本一旦变大，最近邻变贵，显存也被码本吃回去。加法量化是折中：用 \\(M\\) 本较小的码，\\(M\\) 次查表相加逼近高分辨 VQ，码本体积与搜索成本按加法分解，而不是按笛卡尔积爆炸。</p><p>LLM 层宽大、层数多，码本不能每层都做成视觉里那种巨型表。还要在校准激活上对层输出做重建，否则码字对 WikiText 好看、对下一层输入的分布不看。问题是：在 2–3 bit 每参数的预算内，如何布置分组维度、码本个数与比特，使重建误差低于均匀 GPTQ，并且推理时查表核跑得动。</p><h3 id="加法量化把一行拆成多本码字之和" tabindex="-1">加法量化把一行拆成多本码字之和 <a class="header-anchor" href="#加法量化把一行拆成多本码字之和" aria-label="Permalink to &quot;加法量化把一行拆成多本码字之和&quot;">​</a></h3><p>对一组 \\(g\\) 维子向量 \\(w\\)，</p> \\[w \\approx \\sum_{m=1}^{M} C_m[i_m], \\]<p>其中 \\(C_m\\in\\mathbb{R}^{K\\times g}\\) 是第 \\(m\\) 本码，\\(i_m\\) 是索引。<span class="marginnote">类比点套餐：一道菜（权重子向量）不存整份菜谱，而是存「主食编号 + 主菜编号 + 饮品编号」三个短索引，端上来的菜是三样加在一起。每个索引只要几个 bit，组合出的菜色却接近一本巨型码表——这就是「比特花在选哪几个码字」的含义。</span>存储是 \\(M\\log_2 K\\) 比特加码本本身均摊到每参数的开销。常见配置用多个 8-bit 索引或更碎的组合，使平均比特落到 2-bit 附近（论文表中的 \\(1\\times16\\)、\\(2\\times8\\) 一类记法是「码本数 × 每本比特」）。\\(g\\) 太大，码本表达力不够；\\(g\\) 太小，退回接近标量量化。这是结构超参，不是训练超参。</p><p><span class="marginnote">AQLM 压缩的是权重。激活在原文主实验里仍是较高精度。不要把「extreme compression」理解成 W2A2。KV 也不在这篇合同里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化：按分组把权重切成子向量，用残差 k-means 或类似程序逐本填码本——先拟合第一本，残差再拟合第二本，类似残差向量量化，但是最终前向是诸本<strong>相加</strong>而不是只走残差链的最后一本。编码：为每个子向量选一组索引，可用交替搜索（固定其它本，更新一本的索引）。量化感知微调（论文称 PV-tuning 一类）：在校准激活上对码本条目——有时也对索引分配——做块级或层级的重建下降，直通梯度穿过查表。这一步往往比初始 AQ 编码更能移动 PPL，是帕累托曲线上「AQLM 点」真正可引用的原因。</p>',13)),(t(),A(l,null,{default:i(()=>[r(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22FP16%20%E5%88%86%E7%BB%84%E5%AD%90%E5%90%91%E9%87%8F%22%5D%20--%3E%20AQ%5B%22%E6%AE%8B%E5%B7%AE%E5%BC%8F%E5%A1%AB%20M%20%E6%9C%AC%E7%A0%81%22%5D%0A%20%20AQ%20--%3E%20IDX%5B%22%E4%B8%BA%E6%AF%8F%E7%BB%84%E9%80%89%E7%B4%A2%E5%BC%95%20i_m%22%5D%0A%20%20IDX%20--%3E%20PV%5B%22%E6%A0%A1%E5%87%86%E4%B8%8A%E5%BE%AE%E8%B0%83%E7%A0%81%E6%9C%AC%22%5D%0A%20%20PV%20--%3E%20SUM%5B%22%CE%A3%20C_m%5Bi_m%5D%22%5D%0A%20%20X%5B%22A16%20%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20GEMM%5B%22%E6%9F%A5%E8%A1%A8%E5%8F%8D%E9%87%8F%E5%8C%96%E5%90%8E%E4%B9%98%22%5D%0A%20%20SUM%20--%3E%20GEMM%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>主表：LLaMA-2 7B/13B/70B 在约 2-bit 每参数时 WikiText 困惑度进入与 QuIP# 同场可比较的区间，并随是否 PV-tuning、平均比特的微小变化而左右。零样本任务用来防止只刷 PPL。作者强调应报告 <strong>平均比特</strong>（含码本开销），而不是只报索引比特——码本在 7B 上均摊更大，在 70B 上更便宜。把 7B 的「2-bit」和 70B 的「2-bit」当成同一压缩比，会低估小模型的码本税。<span class="marginnote">代个数：一本 65536 行、每行 8 个 16 位数的码本约 1 MB；摊到 7B 参数约 0.0012 bit/参数，摊到 70B 只有约 0.0001 bit。同一套码本，模型越大税越轻——这就是「名义 2-bit」在 7B 上实际更接近 2.4-bit 的来源。</span></p><h3 id="pv-tuning-才把码本推到帕累托前沿" tabindex="-1">PV-tuning 才把码本推到帕累托前沿 <a class="header-anchor" href="#pv-tuning-才把码本推到帕累托前沿" aria-label="Permalink to &quot;PV-tuning 才把码本推到帕累托前沿&quot;">​</a></h3><p>没有微调的加法码本，只是一种更好的初始化网格。校准下降让码字迁到该层权重与校准激活共同定义的误差面上，类似于 QuIP# 微调 E8 代表点，但参数化更自由：加法码本不必落在格上。自由的代价是最近邻没有格的代数结构，推理更依赖查表与累加。原文把「是否微调」写成必须披露的开关；拿未微调的 AQLM 去打微调过的 QuIP#，或反过来，都不是公平点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均匀格子把比特均分给每个标量。加法码本把比特花在离散选择上：两本 8-bit 码、8 维一组，表达的是 \\(256+256\\) 个向量的和所张成的集合，远大于 \\(4^8\\) 个立方格点里真正用得上的那一部分——前提是权重子向量确实聚集在低复杂度的并上。</p>',5)),(t(),A(l,null,{default:i(()=>[r(E,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E4%B8%80%E7%BB%84%208%20%E7%BB%B4%E6%9D%83%E9%87%8D%E5%AD%90%E5%90%91%E9%87%8F%22%5D%20--%3E%20U%5B%22%E5%9D%87%E5%8C%80%202-bit%EF%BC%9A%E6%AF%8F%E6%A0%87%E9%87%8F%204%20%E7%94%B5%E5%B9%B3%22%5D%0A%20%20W%20--%3E%20VQ%5B%22%E5%90%91%E9%87%8F%E9%87%8F%E5%8C%96%EF%BC%9A%E4%B8%80%E6%9C%AC%E5%A4%A7%E7%A0%81%E8%A1%A8%E6%9F%A5%E4%B8%80%E6%AC%A1%22%5D%0A%20%20W%20--%3E%20AQ%5B%22%E5%8A%A0%E6%B3%95%E9%87%8F%E5%8C%96%EF%BC%9AM%20%E6%9C%AC%E5%B0%8F%E7%A0%81%E8%A1%A8%E6%9F%A5%20M%20%E6%AC%A1%E5%86%8D%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20U%20--%3E%20U2%5B%22%E6%A0%BC%E5%AD%90%E5%9D%87%E5%8C%80%EF%BC%8C%E6%8A%93%E4%B8%8D%E4%BD%8F%E7%9B%B8%E5%B9%B2%E7%BB%93%E6%9E%84%22%5D%0A%20%20VQ%20--%3E%20V2%5B%22%E8%A1%A8%E8%BE%BE%E5%8A%9B%E5%BC%BA%EF%BC%8C%E4%BD%86%E7%A0%81%E6%9C%AC%E4%B8%8E%E6%9F%A5%E8%A1%A8%E9%83%BD%E8%B4%B5%22%5D%0A%20%20AQ%20--%3E%20A2%5B%22%E7%A0%81%E6%9C%AC%E6%8C%89%E5%8A%A0%E6%B3%95%E5%88%86%E8%A7%A3%EF%BC%8C%E8%A1%A8%E8%BE%BE%E5%8A%9B%E6%8E%A5%E8%BF%91%E5%A4%A7%E8%A1%A8%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p>LLM 权重并非任意，预训练把它们推到可被少量子向量原型近似的区域，AQ 才有效。若某层接近白噪声，码本退化，收益回到 GPTQ。</p><p>查表核的屋顶线：decode 仍带宽墙，2-bit 索引少搬权重；但要把 \\(M\\) 次 gather 合成 \\(g\\) 维向量再乘激活，随机访存可能打满缓存。prefill 算力墙时，反量化后的 GEMM 与 FP16 同类，加速主要来自少从 HBM 取权重。没有为 AQLM 写过的核，质量表不能翻译成 token/s。</p><p><span class="marginnote">Elias Frantar 同时是 GPTQ 作者。AQLM 不是「GPTQ 的 2-bit 版」。GPTQ 补偿均匀网格；AQLM 替换网格本身。相关工作里两者是对照，不是父子。</span></p><h3 id="与-quip-比的是比特–困惑度曲线" tabindex="-1">与 QuIP# 比的是比特–困惑度曲线 <a class="header-anchor" href="#与-quip-比的是比特–困惑度曲线" aria-label="Permalink to &quot;与 QuIP# 比的是比特–困惑度曲线&quot;">​</a></h3><p>单点「2-bit LLaMA-2-7B」会因分组、是否微调、是否含码本比特而翻转胜负。正确引用是：在相同平均比特、相同校准、相同是否微调码本的前提下读曲线。QuIP# 保留格的快速解码；AQLM 保留更自由的并集近似。生产选型还要看现成核：有 Marlin / INT4 时 4-bit 往往更省事；只有在显存把 70B 逼到 2-bit 时，才进入这两篇的赛道。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="查表核与均匀-int-核不能混用检查点" tabindex="-1">查表核与均匀 INT 核不能混用检查点 <a class="header-anchor" href="#查表核与均匀-int-核不能混用检查点" aria-label="Permalink to &quot;查表核与均匀 INT 核不能混用检查点&quot;">​</a></h3><p>AQLM 权重文件是索引加码本，不是分组 INT4。vLLM / transformers 若未注册对应线性模块，会静默失败或错读。<span class="marginnote">初学者容易以为「2-bit 权重」就是每参数 2 bit 的 INT2 张量文件；AQLM 存的是索引加码本，加载器要先建好查表结构。模块没注册时往往不是干脆报错，而是可能静默算错——这是社区复现里最常见的坑。</span>微调码本对校准域敏感，指令与代码模型要分别签字。分组维度与 \\(M\\) 改变时，平均比特和核模板一起变，不能只改一个。嵌入与 <code>lm_head</code> 常常更高比特，报价时应写清「主体层 2-bit」。AQLM 不处理激活异常值；接到 W2A4 上需要另做平滑或旋转。</p><p>训练适配器时，基座前向必须走同一套反量化，否则 LoRA 学在错误的数值表面上。码本条目若在部署期被量化成更低精度，论文数字作废。70B 上码本均摊小、7B 上大，小模型更可能出现「名义 2-bit、实际 2.4-bit 且更慢」。</p><p><span class="marginnote">出处：Egiazarian et al.，<em>Extreme Compression of Large Language Models via Additive Quantization</em>，ICML 2024（arXiv:2401.06118）。实现与核以作者发布的 AQLM 仓库版本为准，不要把社区 fork 的默认比特写成论文表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AQLM 用多码本加法量化表示权重子向量，把 2-bit 预算花在索引而不是均匀电平。</li><li>PV-tuning 在校准上微调码本，是帕累托位置的关键，必须与「仅 AQ 编码」分列。</li><li>与 QuIP# 比较应沿平均比特曲线，并披露码本开销。</li><li>推理原语是查表累加，不是 INT4 GEMM。</li><li>出处：Egiazarian et al.，ICML 2024。</li></ul>',12))])}const Q=o(p,[["render",d]]);export{_ as __pageData,Q as default};
